"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/changelog-pages/variants/01-sidebar";
import View1 from "./components/changelog-pages/variants/02-ledger";
import View2 from "./components/changelog-pages/variants/03-simple";
const variants = {"sidebar":View0,"ledger":View1,"simple":View2};
export interface ArtemisChangelogProps { className?: string; variant?: "sidebar" | "ledger" | "simple"; }
export function ArtemisChangelog({ className, variant = "sidebar" }: ArtemisChangelogProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
